import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEl3,validEl3,advanceEl3,numericEl3,experimentOptions,experimentResult,experimentCases,experimentValid}from './el3-models.js?v=20261023-physicscomplete01';import{showEl3}from './el3-visuals.js?v=20261023-physicscomplete01';export{showEl3};
export function mountEl3(l,p,root,{save,done,feedback}){let ts=tasksForEl3(l.widget.slice(4),l.learnerTier),w=p.widget;w.el3Task??=ts[0].id;w.el3Drafts??={};w.el3Passed??=[];let i=ts.findIndex(t=>t.id===w.el3Task);if(i<0)i=0;let t=ts[i],v=w.el3Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEl3(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.el3Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('el3Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('el3Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEl3">Reveal evidence →</button><p id="el3Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEl3(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#el3Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEl3(c,v.answer);}
else if(t.type==='sequence'){body=field('el3Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEl3">Advance pathway →</button><p id="el3Readout" aria-live="polite"></p>';draw=()=>{showEl3(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#el3Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('el3A',o.labels[0],o.a,v.a)+field('el3B',o.labels[1],o.b,v.b)+'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="el3Prediction" value="'+(v.prediction??'')+'"></label><button class="secondary" id="el3Run">Reveal model output →</button><p id="el3Output"></p>'+field('el3Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showEl3(t.kind,{a:v.a,b:v.b,wiring:v.wiring,revealed:v.ran,title:t.title});$('#el3Output').textContent=v.ran?'Model output: '+Number(r.value.toFixed(3))+' '+o.unit:'Predict first. Use the selected quantities and the relationship explained in Discover.';};valid=()=>!!v.ran&&numericEl3(v.prediction,experimentResult(t.experiment,v.a,v.b).value);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="el3Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="el3Number" type="number" step="any" value="'+(v.number??'')+'">'+field('el3Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEl3(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericEl3(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="el3Evidence"></p><div class="lab-actions"><button class="secondary" id="recordEl3">Record reasoning</button><button class="secondary" id="nextEl3">Next challenge →</button></div><p id="el3Progress"></p>';
const status=()=>{$('#el3Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.el3Passed.includes(t.id)?'Challenge recorded.':'';$('#el3Progress').textContent=ts.filter(t=>w.el3Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='el3A'||id==='el3B'){if(!val){remount();return;}v[id==='el3A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='el3Interpretation'){v.interpretation=val;save();return;}if(id==='el3Prediction'){v.prediction=val;save();return;}if(id==='el3Case'){if(val===''){remount();return;}v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='el3Answer')v.answer=val;else if(id==='el3Next')v.next=val;else if(id==='el3Number')v.number=val;else if(id==='el3Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='el3Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#el3Run'))$('#el3Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Predict a number first.',true);return;}v.ran=true;save();draw();};
if($('#revealEl3'))$('#revealEl3').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEl3(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEl3(t.cases[v.case],v.answer));};
if($('#advanceEl3'))$('#advanceEl3').onclick=()=>{let n=advanceEl3(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEl3').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.el3Passed.includes(t.id))w.el3Passed.push(t.id);p.widgetDone=ts.every(t=>w.el3Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All required settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextEl3').onclick=()=>{if(!w.el3Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.el3Task=ts[(i+1)%ts.length].id;save();remount();};}
